 10	
 11	/**
 12	 * What the host or the dispatch gate refused this account a moment ago.
 13	 *
 14	 * A refused dispatch is not a mission, so nothing the planners read recorded it and the same target or
 15	 * the same origin was offered again on the next login (measured 4 Oct 2026: one account tried one
 16	 * target 21 times in six hours). A player who was told "that planet is online" leaves it alone for a
 17	 * while; this is that memory, read from the receipts the gate already writes.
 18	 *
 19	 * The refusal cools what it blamed for as long as a launched mission cools its target, so a cooling
 20	 * shorter than the span DISPATCH_REFUSALS counts cannot let a repeat land inside it. How long that is
 21	 * lives in `resources/behavior/dispatch-refusals.yaml`, never here.
 22	 */
 23	class RecentRefusals
 24	{
 25	    private const POLICY_FILE = '/resources/behavior/dispatch-refusals.yaml';
 26	
 27	    /** @var array<string, mixed>|null */
 28	    private static ?array $policy = null;
 29	
 30	    /**
 31	     * The two refusals the gate raises about the *target*: a planet that is online or staging says
 32	     * nothing about the body the fleet would leave from, so an origin is never blamed for them.
 33	     */
 34	    private const TARGET_SIDE_REASONS = [
 35	        AiQueueActionReason::TargetActiveAtDispatch->value,
 36	        AiQueueActionReason::TargetStagingAtDispatch->value,
 37	    ];
 38	
 39	    public function target(int $playerId, int $galaxy, int $system, int $position): bool
 40	    {
 41	        return isset($this->refusedTargets($playerId)["{$galaxy}:{$system}:{$position}"]);
 42	    }
 43	
 44	    /**
 45	     * Whether the window holds a refusal that blamed this origin — for one of $reasons when the caller
 46	     * names them, otherwise for whatever the gate said.
 47	     */
 48	    public function origin(int $playerId, int $planetId, string ...$reasons): bool
 49	    {
 50	        return $this->recent($playerId)
 51	            ->reject($this->targetSide(...))
 52	            ->contains(fn (AiActionReceipt $receipt): bool => ($receipt->result['planet_id'] ?? null) === $planetId
 53	                && ($reasons === [] || in_array($receipt->result['reason'] ?? null, $reasons, true)));
 54	    }
 55	
 56	    /**
 57	     * Whether the window holds a refusal of one of this account's own dispatch orders — the lane whose
 58	     * budget belongs to the account rather than to a body or a target.
 59	     *
 60	     * An order that names no target is that lane: an expedition's slot is shared by every planet, so the
 61	     * host's refusal ("too many expeditions at the same time") is the account's, and a player answers it
 62	     * by waiting for a slot to come home rather than by trying the next body for the same answer. Cooling
 63	     * the body alone sent the next login to a sibling and repeated the refusal (measured 4 Oct 2026: one
 64	     * body refused for this five times in six hours). A refusal that names no body either (no owned
 65	     * planet, nothing queueable) is not a dispatch that could have flown, so it is not a lane refusal.
 66	     */
 67	    public function accountLane(int $playerId): bool
 68	    {
 69	        return $this->recent($playerId)->contains(fn (AiActionReceipt $receipt): bool => ($receipt->result['decision'] ?? []) === []
 70	            && ($receipt->result['planet_id'] ?? null) !== null);
 71	    }
 72	
 73	    /**
 74	     * The coordinates the window's refusals named, keyed "g:s:p": a planner holding a candidate list
 75	     * skips them in one read instead of one query per candidate.
 76	     *
 77	     * @return array<string, true>
 78	     */
 79	    public function refusedTargets(int $playerId): array
 80	    {
 81	        $coordinates = [];
 82	
 83	        foreach ($this->recent($playerId) as $receipt) {
 84	            $galaxy = $receipt->result['decision']['target_galaxy'] ?? null;
 85	            $system = $receipt->result['decision']['target_system'] ?? null;
 86	            $position = $receipt->result['decision']['target_position'] ?? null;
 87	
 88	            if ($galaxy !== null && $system !== null && $position !== null) {
 89	                $coordinates["{$galaxy}:{$system}:{$position}"] = true;
 90	            }
 91	        }
 92	
 93	        return $coordinates;
 94	    }
 95	
 96	    /**
 97	     * The own bodies the window's refusals blamed, keyed by planet id.
 98	     *
 99	     * An origin the gate refused is an origin a player leaves alone for a while, and the reason is not
100	     * read: the host raises some of them as free text a planner cannot name ("Not enough units on the
101	     * planet to send the fleet. Units required: colony_ship"), and each one says the dispatch from this
102	     * body did not happen. Only the target-side reasons are excluded.
103	     *
104	     * @return array<int, true>
105	     */
106	    public function refusedOrigins(int $playerId): array
107	    {
108	        $origins = [];
109	
110	        foreach ($this->recent($playerId)->reject($this->targetSide(...)) as $receipt) {
111	            $planetId = $receipt->result['planet_id'] ?? null;
112	
113	            if ($planetId !== null) {
114	                $origins[(int) $planetId] = true;
115	            }
116	        }
117	
118	        return $origins;
119	    }
120	
121	    /** A refusal about the target is no fault of the body the fleet would leave from. */
122	    private function targetSide(AiActionReceipt $receipt): bool
123	    {
124	        return in_array($receipt->result['reason'] ?? null, self::TARGET_SIDE_REASONS, true);
125	    }
126	
127	    /** @return \Illuminate\Support\Collection<int, AiActionReceipt> */
128	    private function recent(int $playerId)
129	    {
130	        return AiActionReceipt::query()
131	            ->where('player_id', $playerId)
132	            ->where('action_type', AiActionType::DispatchFleet->value)
133	            ->where('state', AiReceiptState::Rejected->value)
134	            ->where('created_at', '>', now()->subMinutes($this->coolingMinutes()))
135	            ->get();
136	    }
137	
138	    /**
139	     * The cooling a refusal buys, in minutes, read by name from the behaviour data. Absent data cools
140	     * nothing beyond the moment of the refusal, so a missing file shows up as repeated refusals rather
141	     * than as a silent blackout of every origin.
142	     */
143	    private function coolingMinutes(): int
144	    {
145	        $value = $this->policy()['cooling_minutes'] ?? null;
146	
147	        return is_numeric($value) ? max(0, (int) $value) : 0;
148	    }
149	
150	    /** @return array<string, mixed> */
151	    private function policy(): array
152	    {
153	        if (self::$policy !== null) {
154	            return self::$policy;
155	        }
156	
157	        $path = dirname(__DIR__, 3) . self::POLICY_FILE;
158	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
159	
160	        return self::$policy = is_array($parsed) ? $parsed : [];
161	    }
162	}

