  3	namespace Modules\AI\Domain\Perception;
  4	
  5	use OGame\Services\PlanetService;
  6	
  7	/**
  8	 * Read-only derived signals over the host's public activity marker and intel
  9	 * freshness, computed once for the tactical planners (SP7).
 10	 *
 11	 * The 15-minute activity star is a galaxy-visible fact: `Planet.time_last_update`
 12	 * names which body was touched and when (INT-004/005/010). This reader never
 13	 * writes and never manufactures the marker — it is read, not fabricated.
 14	 */
 15	class ActivityIntelReader
 16	{
 17	    /** The activity star vanishes exactly this many minutes after the body's last update (INT-010). */
 18	    private const ACTIVITY_WINDOW_MINUTES = 15;
 19	
 20	    private const ACTIVITY_WINDOW_SECONDS = self::ACTIVITY_WINDOW_MINUTES * 60;
 21	
 22	    /** Intel types that go stale quickly: loot, fleet and defence change fast (decision-policies.md). */
 23	    private const FAST_TYPES = ['resources', 'ships', 'defense'];
 24	
 25	    public function activityAt(PlanetService $body): bool
 26	    {
 27	        // The planet's stamp is also refreshed by the host's own queue scheduler, so it lights up on every
 28	        // planet in a running universe. An owner with a recorded login older than a week (the host's own
 29	        // inactive rule) is not at the keyboard whatever that stamp says.
 30	        return $body->getMinutesSinceLastUpdate() < self::ACTIVITY_WINDOW_MINUTES && !$this->ownerAway($body);
 31	    }
 32	
 33	    private function ownerAway(PlanetService $body): bool
 34	    {
 35	        $lastLogin = (int) $body->getPlayer()?->getUser()->time;
 36	
 37	        return $lastLogin > 0 && $body->getPlayer()?->isInactive() === true;
 38	    }
 39	
 40	    /**
 41	     * Activity on a moon with none on its planet signals the moon's facilities
 42	     * (phalanx / jump gate) in use while a fleet is in transit (INT-006).
 43	     */
 44	    public function moonOnlyActivity(PlanetService $moon, PlanetService $planet): bool
 45	    {
 46	        return $this->activityAt($moon) && !$this->activityAt($planet);
 47	    }
 48	
 49	    /**
 50	     * Confidence of a report for one intel type, as a fraction of its freshness
 51	     * window. Resources, fleet and defence go stale fast; coordinates and past
 52	     * losses slowly (RAID-005).
 53	     */
 54	    public function intelConfidence(int $observedAt, int $now, int $ttlHours, string $type): float
 55	    {
 56	        $ageSeconds = max(0, $now - $observedAt);
 57	        $windowSeconds = $this->typeWindowSeconds($type, $ttlHours);
 58	        $confidence = 1.0 - ($ageSeconds / $windowSeconds);
 59	
 60	        return max(0.0, min(1.0, $confidence));
 61	    }
 62	
 63	    /**
 64	     * Probability the target is online when the fleet lands, from its last-update
 65	     * stamp alone — the raid-risk input (RAID-004).
 66	     */
 67	    public function activityProbabilityAtEta(PlanetService $body, int $now, int $etaAt): float
 68	    {
 69	        $lastUpdateAt = $body->getUpdatedAt()->getTimestamp();
 70	
 71	        if (($now - $lastUpdateAt) >= self::ACTIVITY_WINDOW_SECONDS) {
 72	            return 0.0;
 73	        }
 74	
 75	        $minutesToArrival = max(0.0, ($etaAt - $now) / 60);
 76	
 77	        // ponytail: exponential decay over the 15-minute window is the smallest
 78	        // honest model for "still online on arrival"; the true session length is
 79	        // a Weibull (H2) and the calibration runs can swap the flat window for it.
 80	        return exp(-$minutesToArrival / self::ACTIVITY_WINDOW_MINUTES);
 81	    }
 82	
 83	    /**
 84	     * The completeness factor a report's sections justify: a probe that returned
 85	     * no fleet or defence section cannot answer "raid it or not" even when fresh,
 86	     * so each missing section halves the confidence and a present one never
 87	     * raises it (INT-003). null = the section was not returned, [] = returned
 88	     * and empty.
 89	     *
 90	     * @param array<string, int>|null $ships
 91	     * @param array<string, int>|null $defense
 92	     */
 93	    public function completenessFactor(?array $ships, ?array $defense): float
 94	    {
 95	        $factor = 1.0;
 96	        if ($ships === null) {
 97	            $factor *= 0.5;
 98	        }
 99	        if ($defense === null) {
100	            $factor *= 0.5;
101	        }
102	
103	        return $factor;
104	    }
105	
106	    private function typeWindowSeconds(string $type, int $ttlHours): int
107	    {
108	        // ponytail: the fast/slow split is sourced (decision-policies.md); the
109	        // 6:1 ratio is a placeholder for the calibration runs, not a measured
110	        // constant. Replacing it changes only this division.
111	        $hours = in_array($type, self::FAST_TYPES, true) ? (int) ceil($ttlHours / 6) : $ttlHours;
112	
113	        return max(1, $hours) * 3600;
114	    }
115	}

  160	     * Writes the one work item that carries the intent out, keyed by the session's
  161	     * own id: a retried session converges on one action, a later session decides
  162	     * again. The payload is whatever the plan approved, so the schedule and the
  163	     * executor always name the same objective.
