  167	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
  168	    {
  169	        // A manager's extra order carries the manager's own key, so the session's objective keeps the
  170	        // primary key and a retried login converges on the same set of orders (architecture step 3).
  171	        $keySuffix = $keySuffix !== '' ? $keySuffix : $this->managerSuffix;
  172	        $this->enqueued = true;
