  176	            [
  177	                'player_id' => $profile->player_id,
  178	                'kind' => $kind,
  179	                'due_at' => $dueAt ?? $this->clock->now(),
  180	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
  181	                'state' => AiWorkState::Pending,
  182	                'payload' => $payload,
