429	    /**
430	     * @param list<object> $rows
431	     * @return array{sessions: int, other: int, errors: int}
432	     */
433	    private function processRows(array $rows): array
434	    {
435	        $ran = ['sessions' => 0, 'other' => 0, 'errors' => 0];
436	
437	        foreach ($rows as $row) {
438	            try {
439	                app()->makeWith(ProcessAiWork::class, ['workItemId' => (int) $row->id])->handle();
440	                $ran[(string) $row->kind === (string) AiWorkKind::RunSession->value ? 'sessions' : 'other']++;
441	            } catch (Throwable $exception) {
442	                $ran['errors']++;
443	                $this->noteError('work item: ' . $exception->getMessage());
444	            }
445	        }
446	
447	        return $ran;
448	    }
