450	    /**
451	     * Say plainly which sidecars answer before an hour of play depends on them. A sidecar that is down costs
452	     * its connect timeout on every call it is tried, which is what made sessions take seconds each.
453	     */
454	    private function probeSidecars(): void
455	    {
456	        $sidecars = [
457	            'fatima (affect)' => config('ai.cognition.fatima.base_url'),
458	            'cbrkit (experience)' => config('ai.cognition.experience.cbrkit.base_url'),
459	            'agentos (memory)' => config('ai.cognition.memory.agentos.base_url'),
460	        ];
461	
462	        foreach ($sidecars as $name => $url) {
463	            $parts = parse_url((string) $url);
464	            if (!is_array($parts) || !isset($parts['host'])) {
465	                $this->warn("SIDECAR {$name}: no base_url configured");
466	
467	                continue;
468	            }
469	
470	            $started = microtime(true);
471	            $socket = @fsockopen($parts['host'], (int) ($parts['port'] ?? 80), $errno, $error, 1.0);
472	            $took = (microtime(true) - $started) * 1000;
473	
474	            if ($socket === false) {
475	                $this->warn(sprintf('SIDECAR %s DOWN at %s (%s): every call will wait out its timeout. Start it, or the sim is slow and plays without it.', $name, $url, $error));
476	
477	                continue;
478	            }
479	
480	            fclose($socket);
481	            $this->line(sprintf('SIDECAR %s up at %s (%.0f ms to connect)', $name, $url, $took));
482	        }
483	    }
