486	    private function dueQuery(array $players): \Illuminate\Database\Query\Builder
487	    {
488	        $now = SimulatedTime::now();
489	
490	        return DB::table('ai_work_items')
491	            ->whereIn('player_id', $players)
492	            ->where(function ($query) use ($now): void {
493	                $query->where(function ($ready) use ($now): void {
494	                    $ready->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
495	                        ->where('due_at', '<=', $now);
496	                })->orWhere(function ($stranded) use ($now): void {
497	                    $stranded->where('state', AiWorkState::Leased->value)->where('lease_until', '<', $now);
498	                });
