502	    /**
503	     * The next instant anything can happen: a work item coming due, a fleet landing, the next
504	     * maintenance pass, the end of the run, or `max-step` of nothing at all. Work that is already
505	     * due but was refused (a claim that will not take it) cannot stall the clock: it waits a minute.
506	     *
507	     * @param list<int> $players
508	     */
509	    private function nextInstant(CarbonImmutable $now, CarbonImmutable $end, CarbonImmutable $nextMaintenance, array $players, int $maxStep): CarbonImmutable
510	    {
511	        $candidates = [$end, $nextMaintenance, $now->addSeconds($maxStep)];
512	
513	        $nextWork = DB::table('ai_work_items')
514	            ->whereIn('player_id', $players)
515	            ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
516	            ->min('due_at');
517	        if ($nextWork !== null) {
518	            // Still due after the drain means the worker refused it (a claim that waits for the waking
519	            // window, an admission that is off). Retrying such an item every simulated minute made a night
520	            // of hundreds of pointless jumps, so it is looked at again in five minutes.
521	            $due = CarbonImmutable::parse($nextWork);
522	            $candidates[] = $due->greaterThan($now) ? $due : $now->addSeconds(min($maxStep, 300));
523	        }
524	
525	        $nextLease = DB::table('ai_work_items')
526	            ->whereIn('player_id', $players)
527	            ->where('state', AiWorkState::Leased->value)
528	            ->min('lease_until');
529	        if ($nextLease !== null) {
530	            $candidates[] = CarbonImmutable::parse($nextLease)->addSecond();
531	        }
532	
533	        $nextArrival = DB::table('fleet_missions')
534	            ->where('processed', 0)->where('canceled', 0)
535	            ->where('time_arrival', '>', $now->getTimestamp())
536	            ->min('time_arrival');
537	        if ($nextArrival !== null) {
538	            $candidates[] = CarbonImmutable::createFromTimestamp((int) $nextArrival);
539	        }
540	
541	        $next = collect($candidates)->sortBy(fn (CarbonImmutable $at): int => $at->getTimestamp())->first();
542	
543	        return $next->lessThanOrEqualTo($now) ? $now->addSeconds(min($maxStep, 60)) : $next;
544	    }
