 3	namespace Modules\AI\Domain\Decision;
 4	
 5	/**
 6	 * Splits a raid on one target into a frontline wave and a follow-up re-plunder wave.
 7	 *
 8	 * The source fixes the split at 7:5 military units and caps each wave's cargo at half of
 9	 * the stock still stored when that wave lands. No combat technology is ingested, so one
10	 * composition unit is valued as one enemy military unit and wave one is sized at the
11	 * defender's fleet plus the 30% of its defense the 70% survival figure leaves exposed.
12	 */
13	final class WaveFarmPlanner
14	{
15	    private const FRONTLINE_SHARE = 7;
16	
17	    private const FOLLOW_UP_SHARE = 5;
18	
19	    private const LIGHT_FIGHTER_SHARE = 5;
20	
21	    private const HEAVY_FIGHTER_SHARE = 1;
22	
23	    private const DEFENSE_SURVIVAL_PERCENT = 70;
24	
25	    private const PLUNDER_CAP_PERCENT = 50;
26	
27	    /**
28	     * @return list<array{
29	     *     wave: int,
30	     *     light_fighters: int,
31	     *     heavy_fighters: int,
32	     *     stored: array{metal: int, crystal: int, deuterium: int},
33	     *     cargo: array{metal: int, crystal: int, deuterium: int}
34	     * }>
35	     */
36	    public function plan(
37	        int $fleetUnits,
38	        int $defenseUnits,
39	        int $metal,
40	        int $crystal,
41	        int $deuterium,
42	    ): array {
43	        $frontlineUnits = $fleetUnits + intdiv($defenseUnits * (100 - self::DEFENSE_SURVIVAL_PERCENT), 100);
44	        $followUpUnits = intdiv($frontlineUnits * self::FOLLOW_UP_SHARE, self::FRONTLINE_SHARE);
45	
46	        $frontline = $this->wave(1, $frontlineUnits, $metal, $crystal, $deuterium);
47	        $followUp = $this->wave(
48	            2,
49	            $followUpUnits,
50	            $metal - $frontline['cargo']['metal'],
51	            $crystal - $frontline['cargo']['crystal'],
52	            $deuterium - $frontline['cargo']['deuterium'],
53	        );
54	
55	        return [$frontline, $followUp];
56	    }
57	
58	    /**
59	     * @return array{
60	     *     wave: int,
61	     *     light_fighters: int,
62	     *     heavy_fighters: int,
63	     *     stored: array{metal: int, crystal: int, deuterium: int},
64	     *     cargo: array{metal: int, crystal: int, deuterium: int}
65	     * }
66	     */
67	    private function wave(int $number, int $units, int $metal, int $crystal, int $deuterium): array
68	    {
69	        $lightFighters = intdiv($units * self::LIGHT_FIGHTER_SHARE, self::LIGHT_FIGHTER_SHARE + self::HEAVY_FIGHTER_SHARE);
70	
71	        return [
72	            'wave' => $number,
73	            'light_fighters' => $lightFighters,
74	            'heavy_fighters' => $units - $lightFighters,
75	            'stored' => ['metal' => $metal, 'crystal' => $crystal, 'deuterium' => $deuterium],
76	            'cargo' => $this->plunderCap($metal, $crystal, $deuterium),
77	        ];
78	    }
79	
80	    /**
81	     * The 50% figure is the limit the source states, so a wave plans that share of the stock
82	     * in front of it and never empties the planet, however much is lying there.
83	     *
84	     * @return array{metal: int, crystal: int, deuterium: int}
85	     */
86	    private function plunderCap(int $metal, int $crystal, int $deuterium): array
87	    {
88	        return [
89	            'metal' => intdiv($metal * self::PLUNDER_CAP_PERCENT, 100),
90	            'crystal' => intdiv($crystal * self::PLUNDER_CAP_PERCENT, 100),
91	            'deuterium' => intdiv($deuterium * self::PLUNDER_CAP_PERCENT, 100),
92	        ];
93	    }
94	}

  220	     * The host delivers a report as a message row carrying `espionage_report_id`;
  221	     * that row is the account's own record, so reading it here publishes only
  222	     * what the account has been told. The actual target state stays with the
  223	     * report and the estimator — no target model reaches a policy from here.
  224	     *
  225	     * @return array<int, array{report_id:int, observed_at:int, expires_at:int, confidence:float, travel_cost:float, activity:bool|null, attack_permitted:bool, score_viable:bool}>
  226	     */
  227	    private function targetReports(int $playerId, PlayerService $player): array
  228	    {
  229	        $now = now();
  230	        $cutoff = $now->copy()->subHours(self::INTEL_TTL_HOURS);
  231	
  232	        $messages = Message::query()
  233	            ->where('user_id', $playerId)
  234	            ->whereNotNull('espionage_report_id')
  235	            ->where('created_at', '>=', $cutoff)
  236	            ->orderByDesc('id')
  237	            ->limit(20)
  238	            ->get(['espionage_report_id', 'created_at']);
  239	
  240	        if ($messages->isEmpty()) {
  241	            return [];
  242	        }
  243	
  244	        $reports = EspionageReport::query()
  245	            ->whereIn('id', $messages->pluck('espionage_report_id')->all())
  246	            ->get()
  247	            ->keyBy('id');
  248	
  249	        $nowTimestamp = (int) $now->timestamp;
  250	
  251	        // The public highscore is the one score both sides can see: a target
  252	        // under ~⅕ of ours cannot defend its loot economically, so it is
  253	        // dropped before the profit test runs (RAID-008).
  254	        $ownScore = (int) (Highscore::query()->where('player_id', $playerId)->value('general') ?? 0);
  255	        $targetUserIds = $reports->pluck('planet_user_id')->unique()->filter()->all();
  256	        $targetScores = $targetUserIds === []
  257	            ? collect()
  258	            : Highscore::query()->whereIn('player_id', $targetUserIds)->get()->keyBy('player_id');
  259	
  260	        // One fleet-mission service for the whole report set: each makeWith()
  261	        // rebuilds it (and the MessageService inside it), and the module reaches
  262	        // it once per report to price the trip.
  263	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
  264	
  265	        return $messages
  266	            ->map(function (Message $message) use ($reports, $nowTimestamp, $player, $ownScore, $targetScores, $fleetMissions): array {
  267	                // The messages column is a foreign key to espionage_reports with
  268	                // no cascade, so every message here has a report by construction.
  269	                /** @var EspionageReport $report */
  270	                $report = $reports->get((int) $message->espionage_report_id);
  271	                $targetScore = $targetScores->get((int) $report->planet_user_id);
  272	
  273	                return [
  274	                    'report_id' => (int) $message->espionage_report_id,
  275	                    'observed_at' => (int) ($message->created_at->timestamp ?? 0),
  276	                    'expires_at' => (int) ($message->created_at?->addHours(self::INTEL_TTL_HOURS)->timestamp ?? 0),
  277	                    // Freshness, downgraded by completeness: a resources-only probe
  278	                    // cannot answer "raid it or not" even when fresh (INT-003).
  279	                    'confidence' => $this->activityIntelReader->intelConfidence(
  280	                        (int) ($message->created_at->timestamp ?? 0),
  281	                        $nowTimestamp,
  282	                        self::INTEL_TTL_HOURS,
  283	                        'resources',
  284	                    ) * $this->activityIntelReader->completenessFactor($report->ships, $report->defense),
  285	                    // A normalized host distance: the planner enforces the exact
  286	                    // fuel cost in its gate, and this lets the scorer prefer the
  287	                    // closer target among what remains (RAID-006).
  288	                    'travel_cost' => $this->travelCost($player, $fleetMissions, $report),
  289	                    // The 15-minute activity star is galaxy-visible, so publishing
  290	                    // it here is a legal observation, not a reach into target state.
  291	                    'activity' => $this->targetActivity($report),
  292	                    // Legality mirrors the host's own AttackMission checks (own body,
  293	                    // vacation, banned, admin) instead of trusting the intel is attackable.
  294	                    'attack_permitted' => $this->attackPermitted($player, $report),
  295	                    'score_viable' => $this->scoreViable($ownScore, $targetScore === null ? 0 : (int) $targetScore->general),
  296	                    // [] is "probed and empty"; null is "not returned" (INT-004).
  297	                    'defenceless' => $report->ships === [] && $report->defense === [],
  298	                ];
  299	            })
  300	            ->all();
  301	    }
  302	
  303	    /**
  304	     * A target scoring under ~⅕ of ours cannot defend economically, so the
  305	     * account does not farm newbies (RAID-008). An unknown own score filters
  306	     * nothing: a young universe has no score row yet, and skipping everything
  307	     * is worse than skipping nothing.
  308	     */
  309	    private function scoreViable(int $ownScore, int $targetScore): bool
  310	    {
  311	        if ($ownScore === 0) {
  312	            return true;
  313	        }
  314	
  315	        return $targetScore >= intdiv($ownScore, self::VIABILITY_SCORE_DIVISOR);
  316	    }
  317	
  318	    /**
  319	     * The distance from the account's nearest planet to the report's target,
  320	     * normalized by the host's own galaxy span, as a 0..1 cost (RAID-006).
  321	     */
  322	    private function travelCost(PlayerService $player, FleetMissionService $fleetMissions, EspionageReport $report): float
  323	    {
  324	        $target = new Coordinate((int) $report->planet_galaxy, (int) $report->planet_system, (int) $report->planet_position);
  325	
  326	        $minDistance = null;
  327	        foreach ($player->planets->all() as $planet) {
  328	            $distance = $fleetMissions->calculateFleetMissionDistance($planet, $target);
  329	            $minDistance = $minDistance === null ? $distance : min($minDistance, $distance);
